use std :: time :: Instant ; use super :: * ; use std :: thread ; use std :: time :: Duration ; impl BenchmarkTimer { # [doc = " Create a new timer with the given name"] pub fn new (name : & str) -> Self { Self { name : name . to_string () , start : Instant :: now () , } } # [doc = " Finish timing and return elapsed duration in milliseconds"] pub fn finish (self) -> u128 { let elapsed = self . start . elapsed () . as_millis () ; eprintln ! ("⏱️  {}: {}ms" , self . name , elapsed) ; elapsed } }